12     template<length_t D, typename T, qualifier Q>
13     GLM_FUNC_QUALIFIER mat<D, D, T, Q> computeCovarianceMatrix(vec<D, T, Q> const* v, size_t n)
14     {
15         return computeCovarianceMatrix<D, T, Q, vec<D, T, Q> const*>(v, v + n);
16     }
