19     template<length_t D, typename T, qualifier Q>
20     GLM_FUNC_QUALIFIER mat<D, D, T, Q> computeCovarianceMatrix(vec<D, T, Q> const* v, size_t n, vec<D, T, Q> const& c)
21     {
22         return computeCovarianceMatrix<D, T, Q, vec<D, T, Q> const*>(v, v + n, c);
23     }
