47     template<length_t D, typename T, qualifier Q, typename I>
48     GLM_FUNC_QUALIFIER mat<D, D, T, Q> computeCovarianceMatrix(I const& b, I const& e, vec<D, T, Q> const& c)
49     {
50         glm::mat<D, D, T, Q> m(0);
51         glm::vec<D, T, Q> v;
52 
53         size_t cnt = 0;
54         for(I i = b; i != e; i++)
55         {
56             v = *i - c;
57             for(length_t x = 0; x < D; ++x)
58                 for(length_t y = 0; y < D; ++y)
59                     m[x][y] += static_cast<T>(v[x] * v[y]);
60             cnt++;
61         }
62         if(cnt > 0)
63             m /= static_cast<T>(cnt);
64 
65         return m;
66     }
