283     template<typename T, qualifier Q>
284     GLM_FUNC_QUALIFIER void sortEigenvalues(vec<2, T, Q>& eigenvalues, mat<2, 2, T, Q>& eigenvectors)
285     {
286         if (eigenvalues[0] < eigenvalues[1])
287         {
288             std::swap(eigenvalues[0], eigenvalues[1]);
289             std::swap(eigenvectors[0], eigenvectors[1]);
290         }
291     }
292 
293     template<typename T, qualifier Q>
294     GLM_FUNC_QUALIFIER void sortEigenvalues(vec<3, T, Q>& eigenvalues, mat<3, 3, T, Q>& eigenvectors)
295     {
296         if (eigenvalues[0] < eigenvalues[1])
297         {
298             std::swap(eigenvalues[0], eigenvalues[1]);
299             std::swap(eigenvectors[0], eigenvectors[1]);
300         }
301         if (eigenvalues[0] < eigenvalues[2])
302         {
303             std::swap(eigenvalues[0], eigenvalues[2]);
304             std::swap(eigenvectors[0], eigenvectors[2]);
305         }
306         if (eigenvalues[1] < eigenvalues[2])
307         {
308             std::swap(eigenvalues[1], eigenvalues[2]);
309             std::swap(eigenvectors[1], eigenvectors[2]);
310         }
311     }
312 
313     template<typename T, qualifier Q>
314     GLM_FUNC_QUALIFIER void sortEigenvalues(vec<4, T, Q>& eigenvalues, mat<4, 4, T, Q>& eigenvectors)
315     {
316         if (eigenvalues[0] < eigenvalues[2])
317         {
318             std::swap(eigenvalues[0], eigenvalues[2]);
319             std::swap(eigenvectors[0], eigenvectors[2]);
320         }
321         if (eigenvalues[1] < eigenvalues[3])
322         {
323             std::swap(eigenvalues[1], eigenvalues[3]);
324             std::swap(eigenvectors[1], eigenvectors[3]);
325         }
326         if (eigenvalues[0] < eigenvalues[1])
327         {
328             std::swap(eigenvalues[0], eigenvalues[1]);
329             std::swap(eigenvectors[0], eigenvectors[1]);
330         }
331         if (eigenvalues[2] < eigenvalues[3])
332         {
333             std::swap(eigenvalues[2], eigenvalues[3]);
334             std::swap(eigenvectors[2], eigenvectors[3]);
335         }
336         if (eigenvalues[1] < eigenvalues[2])
337         {
338             std::swap(eigenvalues[1], eigenvalues[2]);
339             std::swap(eigenvectors[1], eigenvectors[2]);
340         }
341     }
